"""Owned native three-controller / three-broker KRaft fixture, no external service."""
import hashlib,json,os,pathlib,signal,socket,subprocess,tempfile,time,uuid
from contextlib import contextmanager
from confluent_kafka import Producer,Consumer,TopicPartition,KafkaException
from confluent_kafka.admin import AdminClient,NewTopic,ConfigResource,ResourceType

class Cluster:
 def __init__(self,root):
  self.root=pathlib.Path(root);self.nodes={};self.stopped=set();self.handles=[];self.admin_clients={}
  sockets=[]
  try:
   for _ in range(6):
    s=socket.socket();s.bind(('127.0.0.1',0));sockets.append(s)
   numbers=[s.getsockname()[1] for s in sockets]
  finally:
   for s in sockets:s.close()
  self.controller_ports=dict(zip([101,102,103],numbers[:3]));self.broker_ports=dict(zip([1,2,3],numbers[3:]));self.cluster_id=uuid.uuid4().hex[:22]
  self.bootstrap=','.join('127.0.0.1:'+str(x) for x in self.broker_ports.values())
  self.controllers=','.join('127.0.0.1:'+str(x) for x in self.controller_ports.values())
 def start(self):
  voters=','.join(str(i)+'@127.0.0.1:'+str(port) for i,port in self.controller_ports.items())
  for role,ports in [('controller',self.controller_ports),('broker',self.broker_ports)]:
   for node_id,port in ports.items():
    node=self.root/f'{role}-{node_id}';node.mkdir();config=node/'server.properties'
    values=[f'process.roles={role}',f'node.id={node_id}',f'controller.quorum.voters={voters}','controller.listener.names=CONTROLLER','listener.security.protocol.map=BROKER:PLAINTEXT,CONTROLLER:PLAINTEXT','inter.broker.listener.name=BROKER',(f'log.dirs={node}/data-a,{node}/data-b' if role=='broker' else f'log.dirs={node}/data'),f'metadata.log.dir={node}/metadata','num.network.threads=1','num.io.threads=2','background.threads=1','group.coordinator.threads=1','num.recovery.threads.per.data.dir=1','offsets.topic.replication.factor=3','offsets.topic.num.partitions=1','transaction.state.log.replication.factor=3','transaction.state.log.min.isr=2','transaction.state.log.num.partitions=1','group.initial.rebalance.delay.ms=0','auto.create.topics.enable=false','replica.lag.time.max.ms=3000','log.cleaner.dedupe.buffer.size=8388608','log.cleaner.io.buffer.size=524288','log.segment.bytes=10485760','socket.request.max.bytes=10485760']
    if role=='controller':values.append(f'listeners=CONTROLLER://127.0.0.1:{port}')
    else:values.extend([f'listeners=BROKER://127.0.0.1:{port}',f'advertised.listeners=BROKER://127.0.0.1:{port}'])
    config.write_text('\n'.join(values)+'\n')
    env=dict(os.environ,LOG_DIR=str(node/'logs'),KAFKA_HEAP_OPTS='-Xms32m -Xmx'+('64m' if role=='controller' else '128m')+' -XX:ActiveProcessorCount=1',KAFKA_JVM_PERFORMANCE_OPTS='-server -XX:+UseSerialGC -XX:-UsePerfData')
