  env=dict(os.environ,KAFKA_HEAP_OPTS='-Xms16m -Xmx64m -XX:ActiveProcessorCount=1',KAFKA_JVM_PERFORMANCE_OPTS='-XX:+UseSerialGC',LOG_DIR=str(self.root/'cli-logs'))
